// Generated by vibelang from src/ssh/name.ts; the migrate flow writes it again with each batch.
export function sshHostname(target) {
    // Accepted SSH targets end with a hostname or user@hostname, never a remote
    // command. Strip shell quoting for display only; keep the saved target intact.
    return ((target.trim().split(/\s+/).at(-1) ?? "")
        .replace(/["'\\]/g, "")
        .split("@")
        .at(-1) ?? "");
}
export function sshName(config) {
    return config.name || sshHostname(config.target);
}
export function isSshConnecting(stage) {
    return (stage === "connecting" ||
        stage === "checking" ||
        stage === "downloading" ||
        stage === "uploading" ||
        stage === "starting");
}
/** Another window answering the challenge reads as connecting here, not as a prompt of its own. */
export function sshServerState(item) {
    if (isSshConnecting(item.stage) || item.authenticatingElsewhere)
        return "starting";
    if (item.stage === "authentication")
        return "auth";
    if (item.stage === "ready" || item.stage === "failed" || item.stage === "incompatible")
        return item.stage;
    return "stopped";
}
